import json,gzip,sys,collections,re
base=sys.argv[1]; filt=sys.argv[2] if len(sys.argv)>2 else 'all'; N=int(sys.argv[3]) if len(sys.argv)>3 else 40
p=json.load(gzip.open(base+'.json.gz')); syms=json.load(open(base+'.json.syms.json'))
st=syms['string_table']
libmap={}
for li,lib in enumerate(p['libs']):
    for d in syms['data']:
        if d['debug_name']==lib['debugName']:
            libmap[li]=({a:i for a,i in d['known_addresses']},d['symbol_table'])
def short(n):
    n=re.sub(r'<(?:[^<>]|<(?:[^<>]|<[^<>]*>)*>)*>','<>',n) if len(n)>120 else n
    return n[:110]
inc=collections.Counter();slf=collections.Counter();total=0
for t in p['threads']:
    name=t['name']
    if filt=='main' and name!='cur' and name!='mon': continue
    if filt=='workers' and not name.startswith('Thread'): continue
    if filt=='drop' and name!='caliper-drop': continue
    ft=t['funcTable'];fr=t['frameTable'];sk=t['stackTable'];sm=t['samples']
    rt=t['resourceTable']
    fname={}
    for f in range(fr['length']):
        fn=fr['func'][f]; r=ft['resource'][fn]; lib=rt['lib'][r] if r is not None and r>=0 else None
        a=fr['address'][f]; nm=None
        if lib in libmap:
            ka,tab=libmap[lib]
            if a in ka: nm=st[tab[ka[a]]['symbol']]
        fname[f]=nm or f"?{lib}:{a:x}"
    for s in sm['stack']:
        if s is None: continue
        total+=1
        seen=set();first=True
        while s is not None:
            n=fname[sk['frame'][s]]
            if first: slf[n]+=1;first=False
            if n not in seen: inc[n]+=1;seen.add(n)
            s=sk['prefix'][s]
print('total samples',total,'(0.2ms each)')
print('--INCLUSIVE');
for n,c in inc.most_common(N): print(f"{c*0.2:8.1f}ms {short(n)}")
print('--SELF')
for n,c in slf.most_common(25): print(f"{c*0.2:8.1f}ms {short(n)}")
EOF
python3 -I ana.py prof main 45

